``` Java
public class ProtoHelper<T extends GeneratedMessage> {
...
  T defaultInstance;
  Map<String, FieldDescriptor> fieldMap;
  Map<String, Class<?>> valueTypes;

  public ProtoHelper(Class<T> clazz) {
    ...
  }

  public Class<?> getValueType(String field) {
    return valueTypes.get(field);
