@grandseiken Thank you for reporting this. I was able to reproduce it on my machine as well. Here is the problematic parsing code generated by `protoc`:

```
  for (;;) {
    ::std::pair< ::google::protobuf::uint32, bool> p = input->ReadTagWithCutoffNoLastTag(16384u);
    tag = p.first;
    if (!p.second) goto handle_unusual;
    switch (::google::protobuf::internal::WireFormatLite::GetTagFieldNumber(tag)) {
      // repeated int32 a = 2048;
      case 2048: {
        if (static_cast< ::google::protobuf::uint8>(tag) ==
            static_cast< ::google::protobuf::uint8>(16384u)) {
          DO_((::google::protobuf::internal::WireFormatLite::ReadRepeatedPrimitive<
                   ::google::protobuf::int32, ::google::protobuf::internal::WireFormatLite::TYPE_INT32>(
                 3, 16384u, input, this->mutable_a())));
        } else if (static_cast< ::google::protobuf::uint8>(tag) ==
                   static_cast< ::google::protobuf::uint8>(16386u)) {
          DO_((::google::protobuf::internal::WireFormatLite::ReadPackedPrimitiveNoInline<
                   ::google::protobuf::int32, ::google::protobuf::internal::WireFormatLite::TYPE_INT32>(
                 input, this->mutable_a())));
        } else {
          goto handle_unusual;
        }
        break;
      }

      default: {
      handle_unusual:
        if (tag == 0 ||
            ::google::protobuf::internal::WireFormatLite::GetTagWireType(tag) ==
            ::google::protobuf::internal::WireFormatLite::WIRETYPE_END_GROUP) {
          goto success;
        }
        DO_(::google::protobuf::internal::WireFormatLite::SkipField(
            input, tag, &unknown_fields_stream));
        break;
      }
    }
  }
```
I think the problem occurs when we call `input->ReadTagWithCutoffNoLastTag(16384u)`; we're passing too low a cutoff value there because we're not taking into account the possibility of a higher tag due to the packed field having a wire type of 2 instead of 0. This results in the field being treated as an unknown field.

body:
The JsonPrintOptions.always_print_primitive_fields option has the following comment:
```
  // Whether to always print primitive fields. By default primitive fields with
  // default values will be omitted in JSON output. For example, an int32 field
  // set to 0 will be omitted. Set this flag to true will override the default
  // behavior and print primitive fields regardless of their values.
  bool always_print_primitive_fields;
```
but that's the behavior for proto3 type. For proto2, primitive fields with default values is not omitted in the JSON conversion. This leads to [confusion](https://github.com/google/protobuf/issues/2871) and the doc should be updated to include proto2 as well.

