Why are single maps being tagged with `LABEL_REPEATED`?

**test_map.proto**
```
syntax = "proto3";

message Test {
  map<string, string> m = 1;
}
```

**CLI**
```
> protoc --version
libprotoc 3.4.0

> protoc --descriptor_set_out=test_map.desc --include_imports test_map.proto
```

**ProtoReader.java**
```
import com.google.common.io.ByteStreams;
import com.google.protobuf.DescriptorProtos;
import com.google.protobuf.DescriptorProtos.FileDescriptorProto;
import com.google.protobuf.Descriptors;
import com.google.protobuf.Descriptors.Descriptor;
import com.google.protobuf.InvalidProtocolBufferException;
import com.google.protobuf.ProtocolStringList;
import java.io.IOException;
import java.io.InputStream;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

public class ProtoReader {

    public static void main(String[] args) throws IOException {
        final InputStream fdsStream = ProtoReader.class.getClassLoader().getResourceAsStream("test_map.desc");
        final Descriptor desc = fdsBytesToDescriptor("test_map.proto", "Test", ByteStreams.toByteArray(fdsStream));

        System.out.println(desc.toProto());
    }

    private static Descriptor fdsBytesToDescriptor(final String protoFile, final String messageType, byte[] fdsBytes)
        throws InvalidProtocolBufferException {
        final DescriptorProtos.FileDescriptorSet fdSet = DescriptorProtos.FileDescriptorSet.parseFrom(fdsBytes);

        final Map<String, FileDescriptorProto> fdMap = fdSet.getFileList()
            .stream()
            .collect(Collectors.toMap(FileDescriptorProto::getName, Function.identity()));

        final Descriptors.FileDescriptor fd = buildFd(fdMap.get(protoFile), fdMap);

        return fd.findMessageTypeByName(messageType);
    }

    private static Descriptors.FileDescriptor buildFd(
        final DescriptorProtos.FileDescriptorProto fdProto,
        final Map<String, DescriptorProtos.FileDescriptorProto> fdMap
    ) {
        final ProtocolStringList dependencyList = fdProto.getDependencyList();
        final Descriptors.FileDescriptor[] deps = new Descriptors.FileDescriptor[dependencyList.size()];
        for (int i = 0; i < dependencyList.size(); i++) {
            deps[i] = buildFd(fdMap.get(dependencyList.get(i)), fdMap);
        }
        try {
            return Descriptors.FileDescriptor.buildFrom(fdProto, deps);
        } catch (Descriptors.DescriptorValidationException e) {
            throw new RuntimeException(e);
        }
    }
}
```

