### We're trying to migrate from protobuf-2.6.1 to protobuf-3.5.1. 

After reading through official documents, we decide to use **protobuf-3.5.1 + proto2** which should be fully compatible with the existing protos within code base. It built and passed unit tests with few minor changes. However, when we put newly built services online, they kept showing "extensions not found" errors. After some investigation I wrote a simple example below to illustrate :

Example code was put under a temporary directory(common/rpc/temp)：

#### example_options.proto
```protobuf
package example;

import "google/protobuf/descriptor.proto";

extend google.protobuf.ServiceOptions {
  optional int32 example_version = 20000;
}
```
#### example.proto
```protobuf
package example;

import "common/rpc/temp/example_options.proto";

option cc_generic_services = true;

message ShowRequest {
  optional string name = 1;
}

message ShowResponse {
}

service ExampleService {
  option (example_version) = 100;
  rpc Show(ShowRequest) returns (ShowResponse);
}
```
#### employee.h
```c++
#include <string>

#include "google/protobuf/descriptor.h"

namespace example {

class Employee {
 public:
  explicit Employee(const std::string& name);
  void Report();

 private:
  std::string name_;
  static const google::protobuf::MethodDescriptor* method_descriptor;
};

}
```
#### employee.cc
```c++
#include "common/rpc/temp/employee.h"

#include <iostream>
#include "common/rpc/temp/example.pb.h"

namespace example {

const google::protobuf::MethodDescriptor* Employee::method_descriptor =
    nullptr;
    // Assign to nullptr: example_version found
    // Assign to "Show" method: example_version not found
    // ExampleService::descriptor()->FindMethodByName("Show");

Employee::Employee(const std::string& name) : name_(name) { }

void Employee::Report() {
  std::cout << "Employee::Report" << std::endl
            << "    Name: " << name_ << std::endl
            << "    MethodDescriptor: " << method_descriptor << std::endl;
}

}
```
#### main.cc
```c++
#include <iostream>
#include <memory>

#include "google/protobuf/descriptor.pb.h"
#include "common/rpc/temp/example.pb.h"
#include "common/rpc/temp/employee.h"

using example::example_version;
using example::ExampleService;
using example::Employee;

int main() {
  std::cout << "Enter main" << std::endl;

  const auto* descriptor = ExampleService::descriptor();
  const auto& options = descriptor->options();
  if (options.HasExtension(example_version)) {
    std::cout << "example_version found" << std::endl;
  } else {
    std::cout << "example_version not found" << std::endl;
  }

  auto e = std::make_unique<Employee>("Jack");
  e->Report();

  std::cout << "Exit main" << std::endl;
  return 0;
}
```

As mentioned in the comments, actually when **ExampleService::descriptor()** gets called directly or indirectly before main, the extension is missing. This issue seems to be related to descriptors initialization order.

I assume that extension is well supported in **protobuf-3.5.1 + proto2**, but even in proto3, custom options introduced by extensions are still supported. Please help take a look.

For this example proto file:
```
syntax = "proto2";
package etcdserverpb;

import "github.com/gogo/protobuf/gogoproto/gogo.proto";

option (gogoproto.marshaler_all) = true;
option (gogoproto.sizer_all) = true;
option (gogoproto.unmarshaler_all) = true;
option (gogoproto.goproto_getters_all) = false;

message Request {
	optional uint64 ID         =  1 [(gogoproto.nullable) = false];
	optional string Method     =  2 [(gogoproto.nullable) = false];
	optional string Path       =  3 [(gogoproto.nullable) = false];
	optional string Val        =  4 [(gogoproto.nullable) = false];
	optional bool   Dir        =  5 [(gogoproto.nullable) = false];
	optional string PrevValue  =  6 [(gogoproto.nullable) = false];
	optional uint64 PrevIndex  =  7 [(gogoproto.nullable) = false];
	optional bool   PrevExist  =  8 [(gogoproto.nullable) = true];
