echo "JS Decoded seconds : ", $message->getTimestamp()->getSeconds(), PHP_EOL;
echo "JS Decoded nanos   : ", $message->getTimestamp()->getNanos(), PHP_EOL;
echo PHP_EOL;

echo "Convert to and from protobuf:", PHP_EOL;
