I currently write a PHP extension with the help of [PHP-CPP](http://www.php-cpp.com/) to do the validation work, it is quite simple. The code is list below:
```cpp
// STANDARD INCLUDES
#include <iostream>
// SYSTEM INCLUDES
// APPLICATION INCLUDES
#include "phpcpp.h"
#include "google/protobuf/compiler/importer.h"
#include "google/protobuf/descriptor.h"
// USING NAMESPACES
using namespace std;
using namespace google::protobuf;
using namespace google::protobuf::compiler;
// DEFINES
#define get_xxx(con, desc, name) do {con[#name] = desc->name();} while (0)
// MACROS
// EXTERNAL FUNCTIONS
// EXTERNAL VARIABLES
// CONSTANTS
// STRUCTS
// TYPEDEFS
// FORWARD DECLARATIONS

Php::Value parse_msg_field(const FieldDescriptor* fieldDesc)
{
    Php::Value fieldInfo;

    get_xxx(fieldInfo, fieldDesc, name);
    get_xxx(fieldInfo, fieldDesc, is_extension);
    get_xxx(fieldInfo, fieldDesc, cpp_type_name);
    get_xxx(fieldInfo, fieldDesc, is_repeated);

    if (NULL != fieldDesc->containing_oneof())
    {
        get_xxx(fieldInfo, fieldDesc, index_in_oneof);
    }
    else
    {
        fieldInfo["index_in_oneof"] = -1;
    }

    SourceLocation sl;
    fieldDesc->GetSourceLocation(&sl);
    fieldInfo["leading_comments"] = sl.leading_comments;
    fieldInfo["trailing_comments"] = sl.trailing_comments;

    return fieldInfo;
}

Php::Value parse_enum_field(const EnumValueDescriptor* fieldDesc)
{
    Php::Value fieldInfo;

    get_xxx(fieldInfo, fieldDesc, name);
    get_xxx(fieldInfo, fieldDesc, number);

    SourceLocation sl;
    fieldDesc->GetSourceLocation(&sl);
    fieldInfo["leading_comments"] = sl.leading_comments;
    fieldInfo["trailing_comments"] = sl.trailing_comments;

    return fieldInfo;
}

Php::Value parse_enum(const EnumDescriptor* enumDesc)
{
    Php::Value enumInfo;

    get_xxx(enumInfo, enumDesc, name);
    get_xxx(enumInfo, enumDesc, value_count);

    SourceLocation sl;
    enumDesc->GetSourceLocation(&sl);
    enumInfo["leading_comments"] = sl.leading_comments;
    enumInfo["trailing_comments"] = sl.trailing_comments;

    for (int i=0; i<enumDesc->value_count(); ++i)
    {
        const EnumValueDescriptor* fieldDesc = enumDesc->value(i);
        if (NULL == fieldDesc)
        {
            continue;
        }

        enumInfo["values"].set(i, parse_enum_field(fieldDesc));
    }

    return enumInfo;
}

Php::Value parse_msg(const Descriptor* msgDesc)
{
    Php::Value msgInfo;

    get_xxx(msgInfo, msgDesc, name);

    msgInfo["containing_type"] = "";
    const Descriptor* containing_type = msgDesc->containing_type();
    if (NULL != containing_type)
    {
        msgInfo["containing_type"] = containing_type->name();
    }

    get_xxx(msgInfo, msgDesc, field_count);
    get_xxx(msgInfo, msgDesc, oneof_decl_count);
    get_xxx(msgInfo, msgDesc, nested_type_count);
    get_xxx(msgInfo, msgDesc, enum_type_count);
    get_xxx(msgInfo, msgDesc, extension_range_count);
    get_xxx(msgInfo, msgDesc, extension_count);

    SourceLocation sl;
    msgDesc->GetSourceLocation(&sl);
    msgInfo["leading_comments"] = sl.leading_comments;
    msgInfo["trailing_comments"] = sl.trailing_comments;

    for (int i=0; i<msgDesc->field_count(); ++i)
    {
        const FieldDescriptor* fieldDesc = msgDesc->field(i);
        if (NULL == fieldDesc)
        {
            continue;
        }

        msgInfo["fields"].set(i, parse_msg_field(fieldDesc));
    }

    return msgInfo;
}

Php::Value parse_file(const FileDescriptor* fileDesc)
{
    Php::Value fileInfo;

    get_xxx(fileInfo, fileDesc, name);
    get_xxx(fileInfo, fileDesc, package);

    get_xxx(fileInfo, fileDesc, dependency_count);
    get_xxx(fileInfo, fileDesc, public_dependency_count);
    get_xxx(fileInfo, fileDesc, weak_dependency_count);

    get_xxx(fileInfo, fileDesc, message_type_count);
    get_xxx(fileInfo, fileDesc, enum_type_count);

    get_xxx(fileInfo, fileDesc, service_count);
    get_xxx(fileInfo, fileDesc, extension_count);

    return fileInfo;
}

class MyMfec : public MultiFileErrorCollector
{
public:
    MyMfec(Php::Value& result):result_(result){}
    ~MyMfec(){};
    
    void AddError(const string& filename, int line, int column,
        const string& message)
    {
        result_.set(line, message);
    }
private:
    Php::Value& result_;
};

void do_parse_pb2(const string& fileName, Php::Value& result)
{
    string realPath = Php::call("realpath", fileName);
    string dirName  = Php::call("dirname", realPath);
    string baseName = Php::call("basename", realPath);

    DiskSourceTree sourceTree;
    sourceTree.MapPath("", dirName);

    MyMfec errorCollector(result);
    Importer importer(&sourceTree, &errorCollector);

    const FileDescriptor* fileDesc = importer.Import(baseName);
    if (NULL == fileDesc)
    {
        result["file_name"] = realPath;
        result["error_code"] = -1;
        result["error_msg"]  = "parse file failed!";
        return;
    }

    result["file_info"] = parse_file(fileDesc);

    for (int i = 0; i < fileDesc->message_type_count(); ++i)
    {
        const Descriptor* msgDesc = fileDesc->message_type(i);
        if (NULL == msgDesc)
        {
            continue;
        }

        result["messages"].set(i, parse_msg(msgDesc));
    }

    for (int i = 0; i < fileDesc->enum_type_count(); ++i)
    {
        const EnumDescriptor* enumDesc = fileDesc->enum_type(i);
        if (NULL == enumDesc)
        {
            continue;
        }

        result["enums"].set(i, parse_enum(enumDesc));
    }
}

Php::Value parse_bp_2(Php::Parameters &params)
{
    Php::Value result;
    result["error_code"] = 0;
    result["error_msg"]  = "";

    do 
    {
        if (params.empty())
        {
            result["error_code"] = -1;
            result["error_msg"]  = ".proto file path is NOT given!";
            break;
        }

        Php::Value fileName = params[0];
        do_parse_pb2(fileName, result);

    } while (0);
    

    return result;
}

