// package to messages(class), scan the package to load message class on invoke 'findClass(typeUrl)'
private static final Map<String, Set<Class<? extends GeneratedMessageV3>>> ofPackageCache = new ConcurrentHashMap<>();
// conciseTypeUrl to message(class)
private static final Map<String, Class<? extends GeneratedMessageV3>> mapping = new ConcurrentHashMap<>();

public static Optional<Class<? extends GeneratedMessageV3>> findClass(final String protoTypeUrl) {
    if (StringUtils.isBlank(protoTypeUrl)) return Optional.empty();
    final String noPrefixTypeUrl = ProtobufUtils.removeGooglePrefix(protoTypeUrl);
    if (mapping.containsKey(noPrefixTypeUrl)) return Optional.of(mapping.get(noPrefixTypeUrl));

    return OtherUtil.getPackageFromTypeUrl(noPrefixTypeUrl)
            .map(pkg -> ofPackageCache.computeIfAbsent(pkg, k -> ReflectionsUtils.scan(pkg, GeneratedMessageV3.class)))
            .flatMap(classSet -> classSet.stream()
                    .filter(c -> ProtobufUtils.isClassTypeUrl(c, noPrefixTypeUrl))
                    .peek(mc -> mapping.put(noPrefixTypeUrl, mc))
                    .findFirst());
}
