Parsing a proto2 message with extensions from a manually-constructed `CodedInputStream` does not properly deserialize the extensions.

```csharp
        [Test]
        public void TestParseFromCodedInput()
        {
          var message = new TestAllExtensions();
          message.SetExtension(OptionalBoolExtension, true);
          var serialized = message.ToByteArray();

          using (var cis = new CodedInputStream(serialized))
          {
            var other = TestAllExtensions.Parser
              .WithExtensionRegistry(new ExtensionRegistry { OptionalBoolExtension })
              .ParseFrom(cis);

            Assert.True(message.HasExtension(OptionalBoolExtension));

            // ******************************************************
            // FAILS HERE
