            // ******************************************************
            
            Assert.AreEqual(message, other);
            Assert.AreEqual(message.CalculateSize(), other.CalculateSize());
          }
        }
```

This seems to be because the internal `MergeFrom` method that gets called with the stream does not set the parser's `ExtensionRegistry` on the stream. Adding it as below seems to fix the issue, though I'm not sure if there are also other places that would need to be fixed as well.
```diff
        internal void MergeFrom(IMessage message, CodedInputStream codedInput)
        {
            bool originalDiscard = codedInput.DiscardUnknownFields;
            try
            {
                codedInput.DiscardUnknownFields = DiscardUnknownFields;
+               codedInput.ExtensionRegistry = Extensions;
                message.MergeFrom(codedInput);
            }
            finally
            {
                codedInput.DiscardUnknownFields = originalDiscard;
            }
        }
```

**Additional Notes**
It would also be nice if an ExtensionRegistry could be passed directly to a `MessageParser`'s `ParseFrom` method, which I would then expect to be used without needing to construct a new `MessageParser` instance (which the current `WithExtensionRegistry` method does). This seems to be available in the Java API https://github.com/protocolbuffers/protobuf/blob/31d6b4e30e8b09eb7c23b24913805f49ddb5f6c9/java/core/src/main/java/com/google/protobuf/Parser.java#L68

This would save allocations and simplify code that might be operating on the base `MessageParser` type but also needs to respect extensions.

A similar use case is `IMessage`'s `MergeFrom` method.

A way to cover both easily may be to allow an `ExtensionRegistry` to be set on the `CodedInputStream` during construction. Right now it's internal and there is no constructor that exposes it https://github.com/protocolbuffers/protobuf/blob/f20be839276cfc1129c12d89924164624ef3796d/csharp/src/Google.Protobuf/CodedInputStream.cs#L278

