I expect that the redis hash's fieldname is the protobuf msg's fieldname and the value is the binary 
 bytes that msg's field serialized.so i add an function that serialize an protobuf msg to a map(Key:field's number,value:binary bytes that the field's value serialized)

```c++
static PyObject* InternalSerializeToMap(
    CMessage* self, PyObject* args, PyObject* kwargs,
    bool require_initialized) {
  static char* kwlist[] = { "deterministic", 0 };
  PyObject* deterministic_obj = Py_None;
  if (!PyArg_ParseTupleAndKeywords(args, kwargs, "|O", kwlist,
                                   &deterministic_obj)) {
    return NULL;
  }

  int deterministic = PyObject_IsTrue(deterministic_obj);
  if (deterministic < 0) {
    return NULL;
  }

  if (require_initialized && !self->message->IsInitialized()) {
    ScopedPyObjectPtr errors(FindInitializationErrors(self));
    if (errors == NULL) {
      return NULL;
    }
    ScopedPyObjectPtr comma(PyString_FromString(","));
    if (comma == NULL) {
      return NULL;
    }
    ScopedPyObjectPtr joined(
        PyObject_CallMethod(comma.get(), "join", "O", errors.get()));
    if (joined == NULL) {
      return NULL;
    }

    ScopedPyObjectPtr message_module(PyImport_ImportModule(
        "google.protobuf.message"));
    if (message_module.get() == NULL) {
      return NULL;
    }

    ScopedPyObjectPtr encode_error(
        PyObject_GetAttrString(message_module.get(), "EncodeError"));
    if (encode_error.get() == NULL) {
      return NULL;
    }
    PyErr_Format(encode_error.get(),
                 "Message %s is missing required fields: %s",
                 GetMessageName(self).c_str(), PyString_AsString(joined.get()));
    return NULL;
  }

  const size_t size = self->message->ByteSizeLong();
  if (size == 0) {
    return PyBytes_FromString("");
  }

  if (size > INT_MAX) {
    PyErr_Format(PyExc_ValueError,
                 "Message %s exceeds maximum protobuf "
                 "size of 2GB: %zu",
                 GetMessageName(self).c_str(), size);
    return nullptr;
  }

  PyObject* result = PyDict_New();  

  const Descriptor* descriptor = self->message->GetDescriptor();
  const Reflection* message_reflection = self->message->GetReflection();
  std::vector<const FieldDescriptor*> fields;

  if (descriptor->options().map_entry()) {
    for (int i = 0; i < descriptor->field_count(); i++) {
      fields.push_back(descriptor->field(i));
    }
  } else {
    message_reflection->ListFields(*self->message, &fields);
  }

  std::unordered_map<const FieldDescriptor*,PySerializeToMapHelper> coded_out_map;

  for (int i = 0; i < fields.size(); i++) {
    size_t fdSize = self->message->FieldByteSizeLong(fields[i]);
    PyObject* key = PyInt_FromLong(fields[i]->number());
    PyObject* value = PyBytes_FromStringAndSize(NULL, fdSize);
    PySerializeToMapHelper helper;
    helper.fieldSize = fdSize;
    helper.pyBuffer = PyBytes_AS_STRING(value);
    coded_out_map[fields[i]] = helper;
    PyDict_SetItem(result,key,value);
  }

  self->message->SerializeToMapWithCachedSizes(coded_out_map);
  return result;
}

```
