func (o MarshalOptions) marshalToMap(message Message) (map[int32][]byte, error) {
	m := message.ProtoReflect()
	var wire_map map[int32][]byte = make(map[int32][]byte)
	var err error
	o.rangeFields(m, func(fd protoreflect.FieldDescriptor, v protoreflect.Value) bool {
		b, err := o.marshalField(nil, fd, v)
		if err == nil {
			wire_map[int32(fd.Number())] = b
		}
		return err == nil
	})
	return wire_map, err
}
