#include <sys/shm.h>

#include <cstring>
#include <iomanip>
#include <iostream>
#include <mutex>
#include <thread>

using namespace std;

#define Q_SIZE (10)

template <typename Msg_t>
struct Message_struct {
  pthread_mutex_t mtx;
  int front = 0;
  int tail = 0;
  int num_msgs = 0;
  Msg_t msg_queue[Q_SIZE];
};

template <typename Msg_t>
void shm_init(Message_struct<Msg_t>* shm){
  shm->front = shm->tail = 0;
  shm->num_msgs = 0;

  pthread_mutexattr_t attrs;
  pthread_mutexattr_init(&attrs);
  pthread_mutexattr_setpshared(&attrs, PTHREAD_PROCESS_SHARED);
  pthread_mutex_init(&shm->mtx, &attrs);
}

template <typename Msg_t>
Message_struct<Msg_t>* shm_init_receiver(key_t k, Msg_t) {
  Message_struct<Msg_t>* shm;
  int shmid;
  size_t shm_size = sizeof(Message_struct<Msg_t>);

  shmid = shmget(k, shm_size, 0666);
  if (shmid == -1) {
    cout << "get shm failed, error: " << strerror(errno) << endl;
    return nullptr;
  }

  shm = (Message_struct<Msg_t>*)shmat(shmid, nullptr, 0);
  if (shm == reinterpret_cast<void*>(-1)) {
    cout << "attach shm failed." << endl;
    shmctl(shmid, IPC_RMID, 0);
    return nullptr;
  }
  return shm;
}

template <typename Msg_t>
Message_struct<Msg_t>* shm_init_transmitter(key_t k,
                                            Msg_t) {
  Message_struct<Msg_t>* shm;
  int shmid;
  size_t shm_size = sizeof(Message_struct<Msg_t>);

  shmid = shmget(k, shm_size, 0666 | IPC_CREAT /*| IPC_EXCL*/);
  if (shmid == -1) {
    cout << "get shm failed, error: " << strerror(errno) << endl;
    return nullptr;
  }

  shm = (Message_struct<Msg_t>*)shmat(shmid, nullptr, 0);
  if (shm == reinterpret_cast<void*>(-1)) {
    cout << "attach shm failed." << endl;
    shmctl(shmid, IPC_RMID, 0);
    return nullptr;
  }
  return shm;
}

template <typename Msg_t>
void shm_push(Msg_t msg, Message_struct<Msg_t>* shm) {
  pthread_mutex_lock(&shm->mtx);
  if(shm->num_msgs == Q_SIZE){
    pthread_mutex_unlock(&shm->mtx);
    return;
  }
  shm->msg_queue[shm->front] = msg;
  shm->front = (shm->front + 1) % Q_SIZE;
  shm->num_msgs++;
  pthread_mutex_unlock(&shm->mtx);
}

template <typename Msg_t>
bool shm_pop(Message_struct<Msg_t>* shm, Msg_t* msg) {
  pthread_mutex_lock(&shm->mtx);
  if(shm->num_msgs == 0){
    pthread_mutex_unlock(&shm->mtx);
    return false;
  }

  *msg = shm->msg_queue[shm->tail];
  shm->tail = (shm->tail + 1) % Q_SIZE;
  shm->num_msgs--;
  pthread_mutex_unlock(&shm->mtx);
  
  return true;
}
