in the new debug ones you get something like this:

  // int32 propertyOfMessage  = 1;
  if (this->_internal_propertyOfMessage() != 0) {
    target = ::google::protobuf::internal::WireFormatLite::
        WriteInt32ToArrayWithField<1>(
            stream, this->_internal_propertyOfMessage(), target);
