</details>

<details>
<summary>MapField custom enumerator implementation</summary>

```csharp
public LinkedList< KeyValuePair< TKey, TValue > >.Enumerator GetCustomEnumerator( ) => list.GetEnumerator( );
```

</details>

<details>
<summary>RepeatedField custom enumerator implementation</summary>

```csharp
public Enumerator GetCustomEnumerator( ) => new( this );

public struct Enumerator : IEnumerator< T >
{
    private const int UNSET_IDX = -1;
    private readonly RepeatedField< T > repeatedField;

    private int idx;

    internal Enumerator(
        RepeatedField< T > repeatedField )
    {
        this.repeatedField = repeatedField;
        idx = UNSET_IDX;
    }

    public readonly void Dispose( )
    {
    }

    public bool MoveNext( ) => ++idx < repeatedField.count;

    public void Reset( ) => idx = UNSET_IDX;

    readonly object IEnumerator.Current => repeatedField[idx];

    public readonly T Current => repeatedField[idx];
}
```

</details>

<details>
<summary>Benchmark implementations</summary>

```csharp
[MemoryDiagnoser]
[SimpleJob( RuntimeMoniker.Net70 )]
[SimpleJob( RuntimeMoniker.Net48 )]
public class RepeatedFieldEnumeratorBenchmark
{
    private RepeatedField< int > repeatedField;

    [GlobalSetup]
    public void Setup( )
    {
        repeatedField = new RepeatedField< int >( );
        for ( int i = 0;
              i < 10;
              i++ )
        {
            repeatedField.Add( i );
        }
    }

    [Benchmark]
    public int DefaultForeach( )
    {
        int result = 0;
        foreach ( int i in repeatedField )
        {
            result = i;
        }
        return result;
    }

    [Benchmark]
    public int CustomEnumerator( )
    {
        int result = 0;
        using( RepeatedField< int >.Enumerator enumerator = repeatedField.GetCustomEnumerator( ) )
        {
            while ( enumerator.MoveNext( ) )
            {
                result = enumerator.Current;
            }

            return result;
        }
    }

    [Benchmark]
    public int DefaultFor( )
    {
        int result = 0;
        var repeated = repeatedField;
        for ( int i = 0;
              i < repeated.Count;
              i++ )
        {
            result = repeated[ i ];
        }
        return result;
    }
}

[MemoryDiagnoser]
[SimpleJob( RuntimeMoniker.Net70 )]
[SimpleJob( RuntimeMoniker.Net48 )]
public class MapFieldEnumeratorBenchmark
{
    private MapField< int, int > mapField;

    [GlobalSetup]
    public void Setup( )
    {
        mapField = new MapField< int, int >( );
        for ( int i = 0;
              i < 10;
              i++ )
        {
            mapField.Add(
                i,
                i );
        }
    }

    [Benchmark]
    public int DefaultForeach( )
    {
        int result = 0;
        foreach ( KeyValuePair< int, int > keyValuePair in mapField )
        {
            result = keyValuePair.Value;
        }
        return result;
    }

    [Benchmark]
    public int CustomEnumerator( )
    {
        int result = 0;
        using( LinkedList< KeyValuePair< int, int > >.Enumerator enumerator = mapField.GetCustomEnumerator( ) )
        {
            while ( enumerator.MoveNext( ) )
            {
                result = enumerator.Current.Value;
            }

            return result;
        }
    }
}
```

</details>

