        DIR* dir = opendir(name.c_str());
        if (dir != NULL) { // Assuming `dir` is `nullptr`, skip this branch.
            ...
        }
		
        // `nullptr` passed to 1st parameter excepting 'nonnull'
        closedir(dir);
